create extension if not exists pgcrypto;
create type public.tx_status as enum ('draft','pending_approval','approved','posted','rejected','reversed');
create type public.weight_basis as enum ('net_commodity','inclusive_of_bag');
create type public.packing_mode as enum ('loose','bags','either');
create type public.ownership_type as enum ('own','storage');
create type public.godown_ownership as enum ('own','third_party');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role_code text not null default 'operator',is_active boolean not null default true,created_at timestamptz not null default now());
create table public.user_scopes(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),state_code text,godown_id uuid,can_create boolean default true,can_approve boolean default false,unique(user_id,state_code,godown_id));
create table public.commodities(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,category text,default_uom text not null default 'MT',allowed_uoms text[] not null default array['KG','QTL','MT'],inward_packing_mode public.packing_mode not null default 'either',outward_packing_mode public.packing_mode not null default 'either',inward_weight_basis public.weight_basis not null default 'net_commodity',outward_weight_basis public.weight_basis not null default 'net_commodity',inventory_quantity_basis public.weight_basis not null default 'net_commodity',standard_net_weight_per_bag_kg numeric(18,6) not null default 50,standard_empty_bag_tare_kg numeric(18,6) not null default 0.12,bags_mandatory_inward boolean not null default false,bags_mandatory_outward boolean not null default false,crop_year_mandatory boolean not null default true,quality_mandatory_inward boolean not null default false,default_rate_uom text not null default 'MT',fumigation_interval_days integer,is_active boolean not null default true,effective_from date not null default current_date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.commodity_rule_versions(id uuid primary key default gen_random_uuid(),commodity_id uuid not null references public.commodities(id),version_no integer not null,snapshot jsonb not null,effective_from timestamptz not null default now(),effective_to timestamptz,created_by uuid references public.profiles(id),unique(commodity_id,version_no));
create table public.crop_years(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,is_active boolean default true);
create table public.quality_marks(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,sort_order integer default 0,is_active boolean default true);
create table public.parties(id uuid primary key default gen_random_uuid(),code text unique,name text not null,party_types text[] not null default '{}',gstin text,pan text,state_code text,is_active boolean default true);
create table public.banks(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,branch text,is_active boolean default true);
create table public.collateral_managers(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,contact text,is_active boolean default true);
create table public.godowns(id uuid primary key default gen_random_uuid(),code text not null unique,full_name text not null,short_name text,address_line_1 text,address_line_2 text,village_taluk text,district text,state text not null,state_code text not null,pincode text,gstin text,ownership public.godown_ownership not null default 'own',third_party_owner text,warehouse_provider text,agreement_reference text,agreement_start date,agreement_end date,size_sq_ft numeric(18,2),capacity_qty_kg numeric(18,3),open_or_covered text,responsible_employee text,contact_number text,map_enabled boolean default true,is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.godown_zones(id uuid primary key default gen_random_uuid(),godown_id uuid not null references public.godowns(id),code text not null,name text not null,capacity_qty_kg numeric(18,3),map_data jsonb default '{}',is_active boolean default true,unique(godown_id,code));
create table public.document_sequences(id uuid primary key default gen_random_uuid(),sequence_key text not null unique,current_value bigint not null default 0,updated_at timestamptz default now());
create table public.inventory_transactions(id uuid primary key default gen_random_uuid(),reference_no text unique,transaction_type text not null,subtype text,transaction_date date not null default current_date,status public.tx_status not null default 'draft',maker_user_id uuid not null references public.profiles(id),approver_user_id uuid references public.profiles(id),approved_at timestamptz,posted_at timestamptz,reversed_transaction_id uuid references public.inventory_transactions(id),remarks text,source_reference text,tally_invoice_no text,commercial_value numeric(20,2),metadata jsonb not null default '{}',created_at timestamptz default now());
create table public.lots(id uuid primary key default gen_random_uuid(),lot_no text unique,commodity_id uuid not null references public.commodities(id),crop_year_id uuid references public.crop_years(id),quality_mark_id uuid references public.quality_marks(id),owner_type public.ownership_type not null default 'own',owner_party_id uuid references public.parties(id),godown_id uuid not null references public.godowns(id),zone_id uuid references public.godown_zones(id),form public.packing_mode not null default 'bags',parent_lot_ids uuid[] not null default '{}',source_lineage jsonb not null default '[]',commodity_rule_snapshot jsonb not null,created_by_transaction_id uuid references public.inventory_transactions(id),status text not null default 'open',created_at timestamptz default now());
create table public.stock_ledger_entries(id bigserial primary key,transaction_id uuid not null references public.inventory_transactions(id),entry_no integer not null,lot_id uuid not null references public.lots(id),entry_date date not null,entry_type text not null,quantity_kg numeric(20,6) not null,bags numeric(20,3) not null default 0,commercial_quantity_kg numeric(20,6) not null default 0,cost_value numeric(20,2) not null default 0,bag_weight_effect_kg numeric(20,6) not null default 0,godown_id uuid not null references public.godowns(id),zone_id uuid references public.godown_zones(id),sales_order_id uuid,metadata jsonb default '{}',created_at timestamptz default now(),unique(transaction_id,entry_no));
create table public.fifo_layers(id uuid primary key default gen_random_uuid(),lot_id uuid not null references public.lots(id),source_transaction_id uuid not null references public.inventory_transactions(id),layer_date date not null,original_qty_kg numeric(20,6) not null,remaining_qty_kg numeric(20,6) not null,cost_per_kg numeric(20,8) not null,original_value numeric(20,2) not null,metadata jsonb default '{}',created_at timestamptz default now());
create table public.fifo_consumptions(id bigserial primary key,outward_transaction_id uuid not null references public.inventory_transactions(id),fifo_layer_id uuid not null references public.fifo_layers(id),quantity_kg numeric(20,6) not null,cost_value numeric(20,2) not null,created_at timestamptz default now());
create table public.sales_orders(id uuid primary key default gen_random_uuid(),order_no text unique,customer_id uuid not null references public.parties(id),commodity_id uuid not null references public.commodities(id),crop_year_id uuid references public.crop_years(id),quality_mark_id uuid references public.quality_marks(id),order_qty_kg numeric(20,6) not null,cancelled_qty_kg numeric(20,6) not null default 0,rate_per_mt numeric(20,2),delivery_due_date date,status text not null default 'open',created_at timestamptz default now());
alter table public.stock_ledger_entries add constraint fk_ledger_sales_order foreign key(sales_order_id) references public.sales_orders(id);
create table public.stock_controls(id uuid primary key default gen_random_uuid(),control_type text not null,lot_id uuid not null references public.lots(id),sales_order_id uuid references public.sales_orders(id),pledge_id uuid,quantity_kg numeric(20,6) not null,status text not null default 'active',reference_no text,created_by_transaction_id uuid references public.inventory_transactions(id),created_at timestamptz default now());
create table public.bank_pledges(id uuid primary key default gen_random_uuid(),pledge_no text unique,bank_id uuid not null references public.banks(id),collateral_manager_id uuid references public.collateral_managers(id),bank_reference text,collateral_manager_number text,pledge_date date not null,due_date date,bank_value numeric(20,2),funding_done numeric(20,2),status text not null default 'active',created_at timestamptz default now());
create table public.pledge_lots(id uuid primary key default gen_random_uuid(),pledge_id uuid not null references public.bank_pledges(id),lot_id uuid not null references public.lots(id),pledged_qty_kg numeric(20,6) not null,released_qty_kg numeric(20,6) not null default 0,unique(pledge_id,lot_id));
alter table public.stock_controls add constraint fk_control_pledge foreign key(pledge_id) references public.bank_pledges(id);
create table public.pledge_releases(id uuid primary key default gen_random_uuid(),release_no text unique,pledge_id uuid not null references public.bank_pledges(id),release_date date not null,released_qty_kg numeric(20,6) not null,bank_release_reference text,collateral_release_reference text,funding_reduced numeric(20,2),transaction_id uuid references public.inventory_transactions(id),created_at timestamptz default now());
create table public.weighments(id uuid primary key default gen_random_uuid(),reference_no text unique,external_slip_no text,entry_date date not null,vehicle_no text,party_id uuid references public.parties(id),commodity_id uuid references public.commodities(id),net_entered_qty numeric(20,6) not null,uom text not null,bags numeric(20,3) default 0,inventory_qty_kg numeric(20,6),commercial_qty_kg numeric(20,6),linked_transaction_id uuid references public.inventory_transactions(id),status text default 'draft',attachment_path text,created_at timestamptz default now());
create table public.fumigations(id uuid primary key default gen_random_uuid(),reference_no text unique,fumigation_date date not null,godown_id uuid not null references public.godowns(id),chemical text,chemical_batch text,dosage text,chemical_qty numeric(20,3),contractor text,responsible_employee text,start_at timestamptz,release_at timestamptz,coverage_status text,certificate_no text,next_due_date date,remarks text,created_at timestamptz default now());
create table public.fumigation_lots(id uuid primary key default gen_random_uuid(),fumigation_id uuid not null references public.fumigations(id),lot_id uuid not null references public.lots(id),treated_qty_kg numeric(20,6) not null,unique(fumigation_id,lot_id));
create table public.period_closings(id uuid primary key default gen_random_uuid(),period_start date not null,period_end date not null,state_code text,gstin text,status text not null default 'open',closed_by uuid references public.profiles(id),closed_at timestamptz,reopened_by uuid references public.profiles(id),reopened_at timestamptz,reopen_reason text,unique(period_start,period_end,state_code,gstin));
create table public.import_batches(id uuid primary key default gen_random_uuid(),module text not null,file_name text not null,file_hash text not null unique,status text not null default 'uploaded',total_rows integer default 0,valid_rows integer default 0,error_rows integer default 0,storage_path text,created_by uuid references public.profiles(id),created_at timestamptz default now());
create table public.import_rows(id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.import_batches(id) on delete cascade,row_no integer not null,payload jsonb not null,errors jsonb default '[]',status text default 'pending',created_transaction_id uuid references public.inventory_transactions(id));
create table public.alerts(id uuid primary key default gen_random_uuid(),alert_type text not null,severity text not null,title text not null,message text not null,entity_type text,entity_id uuid,due_date date,status text not null default 'open',created_at timestamptz default now(),resolved_at timestamptz);
create table public.audit_events(id bigserial primary key,user_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,details jsonb default '{}',created_at timestamptz default now());
create table public.attachments(id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,bucket text not null,path text not null,file_name text not null,mime_type text,file_size bigint,uploaded_by uuid references public.profiles(id),created_at timestamptz default now());
create or replace function public.prevent_mutation() returns trigger language plpgsql as $$begin raise exception 'Append-only table: update/delete is not permitted';end$$;
create trigger ledger_no_update before update or delete on public.stock_ledger_entries for each row execute function public.prevent_mutation();
create trigger audit_no_update before update or delete on public.audit_events for each row execute function public.prevent_mutation();
